(()=>{'use strict';
const customers=[{id:'A',name:'ABC TRADING PTE. LTD.',country:'Singapore',currency:'USD',term:'30% + 70%',due:5000,owner:'LIM',contact:'Alex Tan',email:'accounts@example.com',phone:'+65 6000 0000',address:'18 Example Road, Singapore'},{id:'B',name:'HORIZON WHOLESALE LTD.',country:'United Kingdom',currency:'GBP',term:'14 days',due:0,owner:'LIM',contact:'Chris Lee',email:'finance@example.com',phone:'+44 20 0000 0000',address:'25 Example Street, London'},{id:'C',name:'PACIFIC GOODS SDN. BHD.',country:'Malaysia',currency:'MYR',term:'Cash',due:2500,owner:'TAN',contact:'Sam Wong',email:'office@example.com',phone:'+60 3 0000 0000',address:'8 Example Avenue, Kuala Lumpur'}];
const invoices=[{customer:'A',period:'May 2026',number:'NCT-INV-000001',date:'18-05-26',currency:'USD',amount:12000,due:5000,cost:39150,profit:8250,gp:17.41,comm:'Pending'},{customer:'A',period:'April 2026',number:'NCT-INV-000002',date:'22-04-26',currency:'USD',amount:8000,due:0,cost:25000,profit:6600,gp:20.89,comm:'Comm. Paid'},{customer:'B',period:'May 2026',number:'GHR-INV-000003',date:'12-05-26',currency:'GBP',amount:10000,due:0,cost:41000,profit:7000,gp:14.58,comm:'Pending'},{customer:'C',period:'May 2026',number:'NCT-INV-000004',date:'08-05-26',currency:'MYR',amount:2500,due:2500,cost:1800,profit:700,gp:28,comm:'Pending'}];
let view='dashboard',scope='LIM',customer='A',query='';const $=id=>document.getElementById(id),money=n=>n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const list=()=>customers.filter(c=>scope==='ALL'||c.owner===scope),selectedInvoices=()=>invoices.filter(i=>list().some(c=>c.id===i.customer));
const cell=(v,n=false)=>'<td'+(n?' class="numeric"':'')+'>'+v+'</td>',table=(heads,rows,cls='')=>'<section class="panel"><div class="scroll"><table class="'+cls+'"><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table>'+(rows.length?'':'<div class="empty">No matching records.</div>')+'</div><div class="footer"><span>'+rows.length+' records</span><span>MASTER · Sales Management</span></div></section>',title=(name,extra='')=>'<div class="heading"><h1>'+name+'</h1>'+extra+'</div>',badge=(s,paid=false)=>'<span class="status'+(paid?' paid':'')+'">'+s+'</span>';
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('area').textContent='Sales Management · '+(scope==='ALL'?'All salespeople':scope);let html='';
if(view==='dashboard'){const rows=list().filter(c=>c.name.toLowerCase().includes(query.toLowerCase()));html=title('Sales Dashboard','<input id="search" aria-label="Search customer" placeholder="Search customer" value="'+esc(query)+'">')+table(['Customer','Country','Currency','Term','Current Due','Entry'],rows.map(c=>'<tr>'+cell('<b>'+c.name+'</b>')+cell(c.country)+cell(c.currency)+cell(c.term)+cell('<span class="'+(c.due?'due':'')+'">'+c.currency+' '+money(c.due)+'</span>',true)+cell('<button class="entry" data-entry="'+c.id+'">Entry →</button>',true)+'</tr>'));}
else if(view==='customer'){const c=list().find(c=>c.id===customer)||list()[0];customer=c.id;html=title('Customers','<select id="customer" aria-label="Customer">'+list().map(x=>'<option value="'+x.id+'"'+(x.id===c.id?' selected':'')+'>'+x.name+'</option>').join('')+'</select>')+'<section class="customer-head"><div class="customer-title"><h2>'+c.name+'</h2><button id="back">All customers</button></div><div class="customer-info"><div><p><span>Country</span>'+c.country+'</p><p><span>Address</span>'+c.address+'</p></div><div><p><span>Contact</span>'+c.contact+'</p><p><span>Email</span>'+c.email+'</p><p><span>Phone</span>'+c.phone+'</p></div><div><p><span>Currency</span>'+c.currency+'</p><p><span>Term</span>'+c.term+'</p><p><span>Current due</span><b>'+c.currency+' '+money(c.due)+'</b></p></div></div></section>'+table(['Period','Invoice No.','Invoice Amount','Payment Status','Cost','Profit','GP','Transport','Comm Status'],selectedInvoices().filter(i=>i.customer===c.id).map(i=>'<tr>'+cell(i.period)+cell('<b>'+i.number+'</b><small>'+i.date+'</small>')+cell(i.currency+' '+money(i.amount),true)+cell(i.due?badge(i.currency+' '+money(i.due)+' due'):badge('Fully Paid',true),true)+cell('MYR '+money(i.cost),true)+cell('MYR '+money(i.profit),true)+cell(i.gp.toFixed(2)+'%',true)+cell('—',true)+cell(badge(i.comm,i.comm==='Comm. Paid'),true)+'</tr>'),'customers-table');}
else html=title('Commission')+table(['Period','Inv','Amount','Cost','Profit','Others Cost','Net Comm'],selectedInvoices().filter(i=>i.due===0).map(i=>'<tr>'+cell(i.period)+cell('<b>'+i.number+'</b><small>'+customers.find(c=>c.id===i.customer).name+'</small>')+cell(i.currency+' '+money(i.amount),true)+cell('MYR '+money(i.cost),true)+cell('MYR '+money(i.profit),true)+cell('—',true)+cell('—',true)+'</tr>'),'commission-table')+'<p class="note">Fully paid transactions. Commission amounts await Finance.</p>';
$('workspace').innerHTML=html;document.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>{customer=b.dataset.entry;view='customer';render();});$('customer')?.addEventListener('change',e=>{customer=e.target.value;render();});$('back')?.addEventListener('click',()=>{view='dashboard';render();});$('search')?.addEventListener('input',e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos);});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('role').onchange=e=>{scope=e.target.value;query='';render();};render();})();